BEGIN;
CREATE TABLE pg13_member_grants(workspace_id uuid NOT NULL,user_id uuid NOT NULL,capability text NOT NULL CHECK(capability IN ('payments:read','payments:issue','payments:manage','payments:export','workspace:settings','members:manage','product:payments')),allowed boolean NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id,capability),FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) ON DELETE CASCADE);
ALTER TABLE pg13_member_grants ENABLE ROW LEVEL SECURITY;ALTER TABLE pg13_member_grants FORCE ROW LEVEL SECURITY;CREATE POLICY pg13_grants_owner ON pg13_member_grants TO CURRENT_USER USING(true) WITH CHECK(true);REVOKE ALL ON pg13_member_grants FROM PUBLIC,ekmivo_financial_runtime;
CREATE FUNCTION pg13_capability_override(w uuid,a uuid,cap text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE WHEN m.role='owner' THEN NULL WHEN cap LIKE 'payments:%' AND EXISTS(SELECT 1 FROM pg13_member_grants WHERE workspace_id=w AND user_id=a AND capability='product:payments' AND NOT allowed) THEN false ELSE(SELECT allowed FROM pg13_member_grants WHERE workspace_id=w AND user_id=a AND capability=cap) END FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=a $$;
CREATE FUNCTION pg13_grants(w uuid,a uuid,target uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE role text;k text;v jsonb;BEGIN
 role:=pg13_actor(w,a,true);PERFORM pg_advisory_xact_lock(hashtextextended('pg13:control:'||w::text,0));
 IF role<>'owner' OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=target AND workspace_members.role<>'owner') THEN RAISE EXCEPTION 'owner/eligible target required' USING ERRCODE='42501';END IF;
 FOR k,v IN SELECT key,value FROM jsonb_each(b) LOOP IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'boolean grant required' USING ERRCODE='22023';END IF;INSERT INTO pg13_member_grants(workspace_id,user_id,capability,allowed) VALUES(w,target,k,(v::text)::boolean) ON CONFLICT(workspace_id,user_id,capability) DO UPDATE SET allowed=EXCLUDED.allowed,updated_at=now();END LOOP;
 INSERT INTO pg13_control_audit(workspace_id,actor_id,action,resource_id) VALUES(w,a,'member-grants',target);RETURN jsonb_build_object('saved',true);
END $$;
CREATE FUNCTION pg13_transfer_owner(w uuid,a uuid,target uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('pg13:control:'||w::text,0));
 IF pg13_actor(w,a,true)<>'owner' OR target=a OR NOT EXISTS(SELECT 1 FROM workspace_members m JOIN app_users u ON u.id=m.user_id WHERE m.workspace_id=w AND m.user_id=target AND u.email_verified_at IS NOT NULL AND u.disabled_at IS NULL) THEN RAISE EXCEPTION 'verified target/current owner required' USING ERRCODE='42501';END IF;
 UPDATE workspace_members SET role='owner' WHERE workspace_id=w AND user_id=target;UPDATE workspace_members SET role='admin' WHERE workspace_id=w AND user_id=a;
 INSERT INTO pg13_control_audit(workspace_id,actor_id,action,resource_id) VALUES(w,a,'ownership-transfer',target);RETURN true;
END $$;
REVOKE ALL ON FUNCTION pg13_capability_override(uuid,uuid,text),pg13_grants(uuid,uuid,uuid,jsonb),pg13_transfer_owner(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pg13_capability_override(uuid,uuid,text),pg13_grants(uuid,uuid,uuid,jsonb),pg13_transfer_owner(uuid,uuid,uuid) TO ekmivo_financial_runtime;
GRANT EXECUTE ON FUNCTION pg13_capability_override(uuid,uuid,text) TO ekmivo_financial_projection;
CREATE OR REPLACE FUNCTION pg10_export_authorized(w uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM workspace_members m JOIN app_users u ON u.id=m.user_id WHERE m.workspace_id=w AND m.user_id=a AND m.role IN ('owner','admin') AND u.disabled_at IS NULL AND pg13_capability_override(w,a,'payments:read') IS DISTINCT FROM false AND pg13_capability_override(w,a,'payments:export') IS DISTINCT FROM false) $$;
GRANT EXECUTE ON FUNCTION pg10_export_authorized(uuid,uuid) TO ekmivo_financial_runtime;
CREATE FUNCTION pg10_invoice_send_authorized(w uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM workspace_members m JOIN app_users u ON u.id=m.user_id WHERE m.workspace_id=w AND m.user_id=a AND m.role IN ('owner','admin') AND u.disabled_at IS NULL AND pg13_capability_override(w,a,'payments:read') IS DISTINCT FROM false AND pg13_capability_override(w,a,'payments:manage') IS DISTINCT FROM false) $$;
REVOKE ALL ON FUNCTION pg10_invoice_send_authorized(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION pg10_invoice_send_authorized(uuid,uuid) TO ekmivo_financial_runtime,ekmivo_financial_projection;
CREATE FUNCTION pg13_team_grants(w uuid,a uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF pg13_actor(w,a,false)<>'owner' THEN RETURN '{}'::jsonb;END IF;RETURN coalesce((SELECT jsonb_object_agg(user_id,grants) FROM(SELECT user_id,jsonb_object_agg(capability,allowed) grants FROM pg13_member_grants WHERE workspace_id=w GROUP BY user_id) g),'{}'::jsonb);END $$;
REVOKE ALL ON FUNCTION pg13_team_grants(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION pg13_team_grants(uuid,uuid) TO ekmivo_financial_runtime;
COMMIT;
